INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca399925-fbb7-48a3-bf93-baffd3c50986', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'What is a QFX5110 Virtual Chassis Fabric (VCF) (variant 4).', '[{"id": "A", "text": "Multiple QFX switches operating as a single logical switch", "is_correct": true}, {"id": "B", "text": "A physical chassis with multiple line cards", "is_correct": false}, {"id": "C", "text": "A virtual router instance", "is_correct": false}, {"id": "D", "text": "An MX series virtual router", "is_correct": false}]', 'VCF allows multiple QFX switches to be interconnected via VCP (Virtual Chassis Ports) to form a single logical switch with unified management (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis', 14.0, '8bb19b01dbda1f4b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de65d7ae-13cd-4780-ada2-9ee9ad82c6bb', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 1, 'remember', 'What is the spine-leaf topology commonly used in modern data centers (variant 4).', '[{"id": "A", "text": "A two-tier topology where leaf switches connect to all spine switches in a full mesh", "is_correct": true}, {"id": "B", "text": "A three-tier topology with core, aggregation, and access layers", "is_correct": false}, {"id": "C", "text": "A ring topology connecting all switches", "is_correct": false}, {"id": "D", "text": "A bus topology with a single backbone", "is_correct": false}]', 'Spine-leaf (clos) topology provides predictable latency by ensuring every leaf connects to every spine with equal hop count (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/data-center/"}', 'Data Center Architecture', 12.0, '3741112f9d867a76_gen_v3', true) ON CONFLICT (id) DO NOTHING;
