INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adb10216-e98e-4b34-9838-47c593e9e61d', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 1, 'apply', 'Which Junos command applies a configuration from a file using the CLI (variant 6).', '[{"id": "A", "text": "load merge /var/tmp/config.conf", "is_correct": true}, {"id": "B", "text": "apply-config /var/tmp/config.conf", "is_correct": false}, {"id": "C", "text": "import config /var/tmp/config.conf", "is_correct": false}, {"id": "D", "text": "set config-file /var/tmp/config.conf", "is_correct": false}]', '''load merge'' reads a configuration file and merges it with the current candidate config. Other load options include ''override'', ''replace'', and ''patch'' (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Junos Configuration', 14.0, 'b9f243886964e77a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13c88074-21e3-4ab2-9cfc-62150f2e3e61', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'remember', 'Which Python library is commonly used to interact with Junos devices via NETCONF (variant 7).', '[{"id": "A", "text": "PyEZ", "is_correct": true}, {"id": "B", "text": "Paramiko", "is_correct": false}, {"id": "C", "text": "Netmiko", "is_correct": false}, {"id": "D", "text": "NAPALM", "is_correct": false}]', 'PyEZ (junos-pyez) is Juniper''s official Python library for automating Junos devices via NETCONF. It provides Device class, configuration management, and RPC calls (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/pyez/"}', 'Junos Automation', 16.0, '42bae6a7fdc9f0d0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
