INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b05281a0-1292-4a3c-9b43-13953a6ab49b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which IPv6 address type is equivalent to a private IPv4 address?', '[{"id": "A", "text": "Unique Local (fc00::/7)", "is_correct": true}, {"id": "B", "text": "Link-Local (fe80::/10)", "is_correct": false}, {"id": "C", "text": "Global Unicast (2000::/3)", "is_correct": false}, {"id": "D", "text": "Multicast (ff00::/8)", "is_correct": false}]', 'Unique Local Unicast addresses (fc00::/7) are the IPv6 equivalent of RFC 1918 private addresses. They are not globally routable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IPv6', 12.0, 'e164be35a68099ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50c825f3-65ea-422d-9fb0-a3d2151e71f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the ''spanning-tree portfast'' command on a Cisco switch?', '[{"id": "A", "text": "Bypasses the listening and learning states for access ports", "is_correct": true}, {"id": "B", "text": "Enables rapid STP on the port", "is_correct": false}, {"id": "C", "text": "Disables STP on the port", "is_correct": false}, {"id": "D", "text": "Configures the port as a trunk", "is_correct": false}]', 'PortFast immediately transitions a port from blocking to forwarding state, bypassing listening and learning. Used only on access ports connected to end hosts.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'STP', 12.0, '3870024e57ceadba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45b50ead-c498-4287-ae6d-9ccf0837b412', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is considered link-state?', '[{"id": "A", "text": "OSPF", "is_correct": true}, {"id": "B", "text": "RIP", "is_correct": false}, {"id": "C", "text": "EIGRP", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'OSPF (Open Shortest Path First) is a link-state routing protocol. It maintains a complete view of the network topology using LSAs.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'Routing Protocols', 12.0, '324845a958553513_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a9dc583-1826-46fd-88ae-820774ff69a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the administrative distance of External EIGRP?', '[{"id": "A", "text": "170", "is_correct": true}, {"id": "B", "text": "20", "is_correct": false}, {"id": "C", "text": "90", "is_correct": false}, {"id": "D", "text": "110", "is_correct": false}]', 'External EIGRP routes (redistributed) have AD 170. Internal EIGRP has AD 90.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'Routing Fundamentals', 12.0, 'f15ff47637247091_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21dc25d7-ca48-4296-9c92-9131b6dc5d2c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which Cisco protocol provides first-hop redundancy?', '[{"id": "A", "text": "HSRP", "is_correct": true}, {"id": "B", "text": "STP", "is_correct": false}, {"id": "C", "text": "CDP", "is_correct": false}, {"id": "D", "text": "LLDP", "is_correct": false}]', 'HSRP (Hot Standby Router Protocol) is Cisco''s FHRP that provides default gateway redundancy by allowing two or more routers to share a virtual IP and MAC address.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipapp_fhrp/"}', 'First Hop Redundancy', 12.0, '070955320def8d81_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d563801-bb77-46b9-88b8-ac64269755a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'What does VLAN 1 represent on a Cisco switch by default?', '[{"id": "A", "text": "The default management VLAN - all ports belong to VLAN 1", "is_correct": true}, {"id": "B", "text": "A reserved VLAN for voice traffic", "is_correct": false}, {"id": "C", "text": "A native VLAN for trunk ports only", "is_correct": false}, {"id": "D", "text": "An unused VLAN for security isolation", "is_correct": false}]', 'By default, all switch ports are in VLAN 1, which also carries management traffic including CDP, VTP, PAgP, and DTP.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'VLAN', 12.0, '43e88ded1e339ab5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('230637c7-52ef-4c58-824d-22a5a69ea1de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of DTP (Dynamic Trunking Protocol) on Cisco switches?', '[{"id": "A", "text": "Automatically negotiates trunking mode between connected switches", "is_correct": true}, {"id": "B", "text": "Dynamically assigns VLANs to access ports", "is_correct": false}, {"id": "C", "text": "Detects topology changes in the network", "is_correct": false}, {"id": "D", "text": "Provides authentication between switches", "is_correct": false}]', 'DTP is a Cisco proprietary protocol that negotiates the trunking mode (access/trunk/dynamic) between two connected switch interfaces.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Trunking', 12.0, '406dbf364c6bb908_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('567afce0-a44e-4119-8153-e1e441fb3b56', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which IPv6 address type is equivalent to a private IPv4 address (variant 2).', '[{"id": "A", "text": "Unique Local (fc00::/7)", "is_correct": true}, {"id": "B", "text": "Link-Local (fe80::/10)", "is_correct": false}, {"id": "C", "text": "Global Unicast (2000::/3)", "is_correct": false}, {"id": "D", "text": "Multicast (ff00::/8)", "is_correct": false}]', 'Unique Local Unicast addresses (fc00::/7) are the IPv6 equivalent of RFC 1918 private addresses. They are not globally routable (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IPv6', 12.0, 'ac81ba428af5630e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b426b20-68e6-4f99-81f8-1d2dcc85de1d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the ''spanning-tree portfast'' command on a Cisco switch (variant 2).', '[{"id": "A", "text": "Bypasses the listening and learning states for access ports", "is_correct": true}, {"id": "B", "text": "Enables rapid STP on the port", "is_correct": false}, {"id": "C", "text": "Disables STP on the port", "is_correct": false}, {"id": "D", "text": "Configures the port as a trunk", "is_correct": false}]', 'PortFast immediately transitions a port from blocking to forwarding state, bypassing listening and learning. Used only on access ports connected to end hosts (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'STP', 12.0, '9c22022f2f7f7dee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a03f4eb-6b2c-45c1-91aa-fa3e2c8a70d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is considered link-state (variant 2).', '[{"id": "A", "text": "OSPF", "is_correct": true}, {"id": "B", "text": "RIP", "is_correct": false}, {"id": "C", "text": "EIGRP", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'OSPF (Open Shortest Path First) is a link-state routing protocol. It maintains a complete view of the network topology using LSAs (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'Routing Protocols', 12.0, 'c57118992f9ccedb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
